function esc(s){ s=String(s==null?'':s); return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function bubbleSvg(points){
  if(!Array.isArray(points)||points.length<1) return {error:'至少 1 个点'};
  var pts=points.map(function(p){ return {x:+p.x, y:+p.y, size:+p.size, label:p.label||''}; });
  if(pts.some(function(p){ return isNaN(p.x)||isNaN(p.y)||!(p.size>=0); })) return {error:'x/y 须为数字，size 须为非负'};
  var xs=pts.map(function(p){return p.x;}), ys=pts.map(function(p){return p.y;}), ss=pts.map(function(p){return p.size;});
  var xmin=Math.min.apply(null,xs), xmax=Math.max.apply(null,xs);
  var ymin=Math.min.apply(null,ys), ymax=Math.max.apply(null,ys);
  var smin=Math.min.apply(null,ss), smax=Math.max.apply(null,ss);
  if(xmin===xmax)xmax=xmin+1; if(ymin===ymax)ymax=ymin+1;
  var pad=28, W=220, H=170, pw=W-pad*2, ph=H-pad*2;
  function sx(x){ return pad+(x-xmin)/(xmax-xmin)*pw; }
  function sy(y){ return pad+ph-(y-ymin)/(ymax-ymin)*ph; }
  function sr(sz){ return smax===smin?14:6+(sz-smin)/(smax-smin)*22; }
  var pal=['#5E6AD2','#10B981','#F5A623','#EF4444','#22D3EE','#A78BFA','#F472B6','#34D399'];
  var parts=[];
  parts.push('<line x1="'+pad+'" y1="'+(H-pad)+'" x2="'+(W-pad)+'" y2="'+(H-pad)+'" stroke="#3A3B3E" stroke-width="1"/>');
  parts.push('<line x1="'+pad+'" y1="'+pad+'" x2="'+pad+'" y2="'+(H-pad)+'" stroke="#3A3B3E" stroke-width="1"/>');
  pts.forEach(function(p,i){
    var cx=sx(p.x), cy=sy(p.y), r=sr(p.size);
    parts.push('<circle cx="'+cx.toFixed(1)+'" cy="'+cy.toFixed(1)+'" r="'+r.toFixed(1)+'" fill="'+pal[i%pal.length]+'" fill-opacity="0.55" stroke="'+pal[i%pal.length]+'" stroke-width="1.2"/>');
    if(p.label) parts.push('<text x="'+cx.toFixed(1)+'" y="'+(cy+r+10).toFixed(1)+'" text-anchor="middle" font-size="10" fill="#A1A1AA">'+esc(p.label)+'</text>');
  });
  var svg='<svg viewBox="0 0 '+W+' '+H+'" xmlns="http://www.w3.org/2000/svg">'+parts.join('')+'</svg>';
  return {svg:svg, n:pts.length};
}
var EXPORTS={bubbleSvg:bubbleSvg};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BubbleChartForgePure = EXPORTS; }
